"""Compile Vulkan GLSL to checked-in SPIR-V arrays. Normal C builds need no compiler.

Regeneration requires glslangValidator (Vulkan SDK or Linux glslang-tools).
--check verifies source and bytecode hashes without requiring that tool.
"""
import argparse
import hashlib
import json
from pathlib import Path
import re
import struct
import subprocess
import tempfile

BACKENDS = Path(__file__).resolve().parents[1]
FOLDER = BACKENDS / 'renderers/vulkan/shaders'

def expanded(source):
    contract = (BACKENDS / 'common/_visual_contract.h').read_text(encoding='utf-8')
    macros = {}
    for line in contract.replace('\\\n', '').splitlines():
        match = re.match(r'#define\s+(\w+)\s+(.*)', line)
        if match:
            strings = re.findall(r'"(?:\\.|[^"\\])*"', match[2])
            if strings: macros[match[1]] = ''.join(json.loads(s) for s in strings)
    code = source.read_text(encoding='utf-8')
    code = re.sub(r'^@(\w+)@\n|@(\w+)@', lambda m: macros[m[1] or m[2]], code, flags=re.M)
    return code

def check():
    stale=[]
    for entry in json.loads((FOLDER / 'manifest.json').read_text(encoding='utf-8')):
        code=expanded(FOLDER / entry['source'])
        target=FOLDER / 'generated' / entry['header'].replace('.h','.spv.h')
        header=target.read_text(encoding='utf-8') if target.exists() else ''
        words=re.findall(r'0x([0-9a-f]{8})u',header)
        binary=b''.join(struct.pack('<I',int(word,16)) for word in words)
        if ('// Source SHA256: '+hashlib.sha256(code.encode()).hexdigest() not in header or
            '// SPIR-V SHA256: '+hashlib.sha256(binary).hexdigest() not in header or
            not binary.startswith(b'\x03\x02\x23\x07')):
            stale.append(str(target.relative_to(BACKENDS)))
    return stale

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check',action='store_true')
    parser.add_argument('--compiler',default='glslangValidator')
    args=parser.parse_args()
    if not args.check:
        with tempfile.TemporaryDirectory(prefix='meek-vulkan-') as directory:
            for entry in json.loads((FOLDER / 'manifest.json').read_text(encoding='utf-8')):
                code=expanded(FOLDER / entry['source'])
                stage='vert' if '.vert.' in entry['source'] else 'frag'
                shader=Path(directory) / ('shader.'+stage); shader.write_text(code,encoding='utf-8')
                output=Path(directory) / 'shader.spv'
                subprocess.run([args.compiler,'--target-env','vulkan1.1','-V',str(shader),'-o',str(output)],check=True)
                binary=output.read_bytes(); words=struct.unpack('<'+'I'*(len(binary)//4),binary)
                name=entry['declaration'].split()[-1].replace('_GLSL','_SPV')
                header='// Generated by backends/tools/compile_vulkan_shaders.py. Do not edit.\n'
                header+='// Source SHA256: '+hashlib.sha256(code.encode()).hexdigest()+'\n'
                header+='// SPIR-V SHA256: '+hashlib.sha256(binary).hexdigest()+'\n'
                header+='static const uint32_t '+name+'[] = {\n'
                for i in range(0,len(words),8): header+='    '+', '.join(f'0x{word:08x}u' for word in words[i:i+8])+',\n'
                header+='};\n'
                (FOLDER / 'generated' / entry['header'].replace('.h','.spv.h')).write_text(header,encoding='utf-8')
    stale=check()
    if stale: print('Stale Vulkan SPIR-V headers:\n'+'\n'.join(stale)); return 1
    print('All 5 Vulkan SPIR-V headers are current'); return 0

if __name__=='__main__': raise SystemExit(main())
